from __future__ import annotations

import csv
import json
from pathlib import Path


def _dump(path: Path, obj, pretty=False):
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2 if pretty else None, separators=None if pretty else (',', ':')), encoding='utf-8')


def build_site(root: Path, articles: list[dict], signals: list[dict], events: list[dict], latest: list[dict], status: dict, sources: list[dict], platform_status: list[dict]):
    site = root / 'site'
    data = site / 'data'
    data.mkdir(parents=True, exist_ok=True)
    site.mkdir(parents=True, exist_ok=True)

    _dump(data / 'latest.json', latest)
    _dump(data / 'events.json', events[:2500])
    _dump(data / 'articles.json', articles[:12000])
    _dump(data / 'signals.json', signals[:6000])
    _dump(data / 'run_status.json', status, pretty=True)
    kinds = {}
    for s in sources:
        k = s.get('kind', 'news')
        kinds[k] = kinds.get(k, 0) + 1
    _dump(data / 'source_summary.json', {'total': len(sources), 'kinds': kinds, 'platform_status': platform_status}, pretty=True)

    with (data / 'latest.csv').open('w', encoding='utf-8-sig', newline='') as f:
        w = csv.writer(f)
        w.writerow(['最后出现', '状态', '分类', '优先级', '可信度', '涉华关联', '事件', '国家/地区', '来源数', '新闻数', '社交数', '平台', '关联实体', '主要原因'])
        for e in latest:
            w.writerow([
                e.get('last_seen'), e.get('status'), e.get('category'), e.get('priority_score'), e.get('confidence_score'),
                e.get('china_relevance_score'), e.get('title'), ', '.join(e.get('countries') or []), e.get('source_count'),
                e.get('news_count'), e.get('social_count'), ', '.join(e.get('platforms') or []), ', '.join(e.get('entities') or []), e.get('reason'),
            ])

    with (data / 'signals.csv').open('w', encoding='utf-8-sig', newline='') as f:
        w = csv.writer(f)
        w.writerow(['时间', '平台', '作者', '内容', '涉华类型', '优先级', '可信度', '关联原因', '链接'])
        for r in signals:
            w.writerow([r.get('published_at') or r.get('collected_at'), r.get('platform'), r.get('author'), r.get('text'), r.get('relation'), r.get('priority_score'), r.get('confidence'), r.get('reason'), r.get('url')])

    (site / '.nojekyll').write_text('', encoding='utf-8')
    (site / 'index.html').write_text(SITE_HTML, encoding='utf-8')


SITE_HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>全球涉华早期信号</title>
<style>
:root{--bg:#0b1020;--panel:#11182b;--card:#151e34;--line:#27324a;--ink:#f4f7fb;--muted:#9aa8bd;--blue:#66a3ff;--red:#ff6b77;--orange:#ffad5a;--green:#5bd6a2;--yellow:#f4d35e;--chip:#202c46;--paper:#f6f7f9;--paperink:#1f2937}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#09101f,#0d1322 36%,#101729);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;min-height:100vh}.wrap{max-width:1280px;margin:auto;padding:0 18px}header{padding:28px 0 18px;border-bottom:1px solid #202a40;background:rgba(8,13,26,.88);backdrop-filter:blur(10px);position:sticky;top:0;z-index:20}.brand{display:flex;gap:14px;align-items:center;justify-content:space-between}.brand h1{font-size:25px;margin:0;letter-spacing:.2px}.brand p{margin:6px 0 0;color:var(--muted);font-size:13px}.pill{border:1px solid var(--line);background:#0f1728;border-radius:999px;padding:7px 11px;color:#cbd5e1;font-size:12px}.tabs{display:flex;gap:6px;margin-top:18px;overflow:auto}.tab{border:0;background:transparent;color:#a8b4c8;padding:10px 13px;border-radius:9px;cursor:pointer;white-space:nowrap}.tab.active{background:#1b2944;color:white}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:18px 0}.metric{background:linear-gradient(145deg,#121c31,#11192b);border:1px solid var(--line);border-radius:14px;padding:15px}.metric strong{display:block;font-size:26px}.metric span{font-size:12px;color:var(--muted)}.notice{background:#111a2d;border:1px solid var(--line);border-radius:12px;padding:12px 14px;color:#bac5d6;font-size:12px;line-height:1.6}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}select,input,a.btn{background:#111a2d;color:#e6ecf5;border:1px solid var(--line);border-radius:9px;padding:9px 11px;text-decoration:none}input{min-width:260px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0 28px}.event{background:linear-gradient(155deg,#141e34,#11192b);border:1px solid var(--line);border-radius:15px;padding:16px;box-shadow:0 10px 30px rgba(0,0,0,.12)}.event:hover{border-color:#3b4a69}.topline{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.tag{font-size:11px;padding:4px 7px;border-radius:999px;background:var(--chip);color:#c7d2e4}.tag.signal{background:#4a3216;color:#ffd08a}.tag.hot{background:#4d1f28;color:#ffb3bb}.tag.ok{background:#15382f;color:#9df0cc}.event h2{font-size:17px;line-height:1.52;margin:10px 0 8px}.meta{font-size:12px;color:var(--muted);line-height:1.55}.reason{font-size:13px;line-height:1.58;color:#cbd5e1;margin:9px 0}.scores{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0}.scoreline{font-size:11px;color:#aab6c9}.bar{height:5px;border-radius:9px;background:#25304a;margin-top:6px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#477dff,#6db4ff)}.bar.conf i{background:linear-gradient(90deg,#4cae86,#6ee7b7)}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.chip{font-size:11px;background:#1b263e;border:1px solid #2a3855;color:#b7c3d6;border-radius:999px;padding:4px 7px}.evidence{border-top:1px solid #25304a;margin-top:12px;padding-top:10px}.evidence summary{cursor:pointer;color:#9ec0ff;font-size:12px}.evi{padding:8px 0;border-bottom:1px dashed #263148;font-size:12px;line-height:1.5}.evi a{color:#8fb7ff;text-decoration:none}.source-type{color:#8c9ab0}.hidden{display:none!important}.paper{background:var(--paper);color:var(--paperink);border-radius:14px;border:1px solid #dde2ea;overflow:auto;margin:12px 0 28px;max-height:70vh}table{border-collapse:collapse;width:100%;min-width:1050px}th,td{padding:9px 10px;border-bottom:1px solid #e7eaf0;text-align:left;vertical-align:top;font-size:12px}th{position:sticky;top:0;background:#eef1f5;z-index:2}.paper a{color:#1f5fae}.status-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0 28px}.status-card{background:#121b2f;border:1px solid var(--line);border-radius:12px;padding:13px}.status-card b{font-size:13px}.status-card p{font-size:12px;color:var(--muted);line-height:1.5;margin:7px 0 0}.footer{color:#7d8ba1;text-align:center;font-size:11px;padding:15px 0 35px}@media(max-width:900px){.summary{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.status-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){header{position:static}.brand{align-items:flex-start}.summary{grid-template-columns:1fr 1fr}.metric{padding:12px}.metric strong{font-size:22px}.wrap{padding:0 10px}.event{padding:13px}.status-grid{grid-template-columns:1fr}input{min-width:100%;width:100%}}
</style></head><body>
<header><div class="wrap"><div class="brand"><div><h1>全球涉华早期信号</h1><p>广泛采集，事件聚类，少量展示。苗头不等媒体确认；优先级与可信度分开。</p></div><span class="pill" id="lastRun">读取中…</span></div><div class="tabs"><button class="tab active" data-view="focus">今日重点</button><button class="tab" data-view="signals">苗头</button><button class="tab" data-view="events">全部事件</button><button class="tab" data-view="raw">原始资料</button><button class="tab" data-view="status">系统状态</button></div></div></header>
<main class="wrap"><div class="summary"><div class="metric"><strong id="mFocus">-</strong><span>24小时重点事件</span></div><div class="metric"><strong id="mSignal">-</strong><span>纯社交苗头</span></div><div class="metric"><strong id="mHigh">-</strong><span>高优先级 ≥75</span></div><div class="metric"><strong id="mMulti">-</strong><span>多来源事件</span></div><div class="metric"><strong id="mSources">-</strong><span>新闻巡检来源</span></div></div><div class="notice" id="notice">正在读取最近一次运行状态……</div><div class="toolbar"><select id="cat"><option value="">全部类别</option></select><select id="statusFilter"><option value="">全部状态</option></select><input id="q" type="search" placeholder="搜事件 / 中国关联实体 / 国家"><a class="btn" href="data/latest.csv">下载重点CSV</a><a class="btn" href="data/signals.csv">下载苗头CSV</a></div>
<section id="focusView" class="view"><div id="focusGrid" class="grid"></div></section>
<section id="signalsView" class="view hidden"><div id="signalGrid" class="grid"></div></section>
<section id="eventsView" class="view hidden"><div id="eventGrid" class="grid"></div></section>
<section id="rawView" class="view hidden"><div class="paper"><table><thead><tr><th>时间</th><th>类型</th><th>来源/平台</th><th>内容</th><th>涉华关系</th><th>链接</th></tr></thead><tbody id="rawBody"></tbody></table></div></section>
<section id="statusView" class="view hidden"><div id="statusGrid" class="status-grid"></div></section><div class="footer">Global China Early Signals · GitHub Actions + GitHub Pages</div></main>
<script>
let D={latest:[],events:[],articles:[],signals:[],status:{},summary:{}}; const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); const dt=s=>{let d=new Date(s);return isNaN(d)?'':d.toLocaleString('zh-CN',{hour12:false})};
function tagClass(s){return s==='苗头'||s==='多源苗头'?'signal':(s==='官方信号'?'ok':(s==='持续发展'?'hot':''))}
function card(e){let ev=(e.evidence||[]).slice(0,12).map(x=>`<div class="evi"><span class="source-type">${esc(x.origin_type==='social'?(x.platform||'社交'):(x.source_kind||'新闻'))}</span> · ${esc(x.source||x.author||'')}<br>${esc(x.title||'')} ${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener">原始链接</a>`:''}</div>`).join('');let chips=[...(e.countries||[]),...(e.entities||[]).slice(0,5)].slice(0,9).map(x=>`<span class="chip">${esc(x)}</span>`).join('');return `<article class="event"><div class="topline"><span class="tag ${tagClass(e.status)}">${esc(e.status)}</span><span class="tag">${esc(e.category)}</span><span class="tag">${esc(e.severity)}</span><span class="tag">${esc(dt(e.last_seen))}</span></div><h2>${esc(e.title)}</h2><div class="meta">新闻 ${e.news_count||0} · 社交 ${e.social_count||0} · 独立来源 ${e.source_count||0}${(e.platforms||[]).length?' · '+esc(e.platforms.join(' / ')):''}</div>${e.reason?`<div class="reason">中国关联：${esc(e.reason)}</div>`:''}<div class="scores"><div><div class="scoreline">优先级 ${e.priority_score||0}</div><div class="bar"><i style="width:${e.priority_score||0}%"></i></div></div><div><div class="scoreline">可信度 ${e.confidence_score||0}</div><div class="bar conf"><i style="width:${e.confidence_score||0}%"></i></div></div></div><div class="chips">${chips}</div><details class="evidence"><summary>展开原始证据 (${(e.evidence||[]).length})</summary>${ev}</details></article>`}
function filterRows(rows){let c=document.getElementById('cat').value,s=document.getElementById('statusFilter').value,q=document.getElementById('q').value.trim().toLowerCase();return rows.filter(e=>(!c||e.category===c)&&(!s||e.status===s)&&(!q||`${e.title} ${e.reason} ${(e.entities||[]).join(' ')} ${(e.countries||[]).join(' ')}`.toLowerCase().includes(q)))}
function render(){document.getElementById('focusGrid').innerHTML=filterRows(D.latest).map(card).join('')||'<div class="notice">当前条件没有重点事件。</div>';let sig=filterRows(D.events.filter(e=>e.social_count>0&&e.news_count===0));document.getElementById('signalGrid').innerHTML=sig.map(card).join('')||'<div class="notice">暂无苗头，或社交连接器尚未配置。</div>';document.getElementById('eventGrid').innerHTML=filterRows(D.events).slice(0,300).map(card).join('')||'<div class="notice">暂无事件。</div>'}
function raw(){let rows=[...D.signals.map(x=>({...x,_t:'苗头',_src:`${x.platform||''} · ${x.author||''}`,_content:x.text})),...D.articles.map(x=>({...x,_t:'新闻',_src:x.source,_content:x.title}))].sort((a,b)=>new Date(b.published_at||b.collected_at)-new Date(a.published_at||a.collected_at)).slice(0,2000);document.getElementById('rawBody').innerHTML=rows.map(r=>`<tr><td>${esc(dt(r.published_at||r.collected_at))}</td><td>${esc(r._t)}</td><td>${esc(r._src)}</td><td>${esc(r._content)}</td><td>${esc(r.relation||'')} ${r.confidence?`(${r.confidence})`:''}</td><td>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">打开</a>`:''}</td></tr>`).join('')}
function statuses(){let ps=D.summary.platform_status||[];document.getElementById('statusGrid').innerHTML=ps.map(x=>`<div class="status-card"><b>${esc(x.platform||x.source||'数据源')} · ${esc(x.status||'unknown')}</b><p>${esc(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail||''))}${x.items!=null?`<br>本轮获取：${x.items}`:''}</p></div>`).join('')||'<div class="notice">暂无社交连接器状态。</div>'}
function stats(){document.getElementById('mFocus').textContent=D.latest.length;document.getElementById('mSignal').textContent=D.events.filter(e=>e.social_count>0&&e.news_count===0).length;document.getElementById('mHigh').textContent=D.latest.filter(e=>e.priority_score>=75).length;document.getElementById('mMulti').textContent=D.latest.filter(e=>e.source_count>=2).length;document.getElementById('mSources').textContent=D.summary.total||0;let cats=[...new Set(D.events.map(x=>x.category).filter(Boolean))].sort();document.getElementById('cat').innerHTML='<option value="">全部类别</option>'+cats.map(x=>`<option>${esc(x)}</option>`).join('');let sts=[...new Set(D.events.map(x=>x.status).filter(Boolean))].sort();document.getElementById('statusFilter').innerHTML='<option value="">全部状态</option>'+sts.map(x=>`<option>${esc(x)}</option>`).join('')}
async function init(){try{let t=Date.now();[D.latest,D.events,D.articles,D.signals,D.status,D.summary]=await Promise.all(['latest','events','articles','signals','run_status','source_summary'].map(n=>fetch(`data/${n}.json?${t}`).then(r=>r.json())));document.getElementById('lastRun').textContent='更新 '+dt(D.status.finished_at);document.getElementById('notice').textContent=`最近运行：${dt(D.status.finished_at)}；新闻候选 ${D.status.items_seen||0}，新入池新闻 ${D.status.items_relevant||0}，新增苗头 ${D.status.signals_relevant||0}，当前事件 ${D.status.events||0}。社交平台未配置或失败时不会阻断新闻更新。`;stats();render();raw();statuses()}catch(e){document.getElementById('notice').textContent='读取数据失败：'+e}}
for(const b of document.querySelectorAll('.tab'))b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));document.getElementById(b.dataset.view+'View').classList.remove('hidden')};document.getElementById('cat').onchange=render;document.getElementById('statusFilter').onchange=render;document.getElementById('q').oninput=render;init();
</script></body></html>'''
